using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class ActorInspectorOperations
{
    public bool property_is_visible(Control inspector,Resource property,GodotObject owner)
    {
        var options=property.Get("options").AsGodotDictionary();if(options.GetValueOrDefault("inspector_hidden",false).AsBool())return false;var resource=owner as Resource;bool actorOwner=resource!=null&&ActorDataOperations.ScriptIs(resource,"res://scripts/actors/core/actor_data.gd");Variant Get(StringName key)=>resource!=null?(actorOwner?_data.get_value(resource,key,default):_data.object_get_value(resource,key,default)):owner.Call("get_value",key);foreach(var value in options.GetValueOrDefault("visible_when_all",new GArray()).AsGodotArray()){var condition=value.AsGodotDictionary();if(!condition.GetValueOrDefault("values",new GArray()).AsGodotArray().Contains(Get(condition.GetValueOrDefault("property","").AsString())))return false;}var visible=options.GetValueOrDefault("visible_when",new Settings()).AsGodotDictionary();if(visible.Count>0){string dependency=visible.GetValueOrDefault("property","").AsString();var value=Get(dependency);var actor=inspector.Get("_actor").As<Resource>();if(resource!=null&&ActorDataOperations.ScriptIs(resource,"res://scripts/actors/core/actor_object_data.gd")&&actor!=null){var path=_timeline.object_animation_path(actor,resource,dependency);var model=Ui<RefCounted>(inspector,"model");var clip=_timeline.clip_for_actor_id(model,actor.Get("id").AsString());if(path.Length>0&&clip!=null)value=_animation.sampled_value(actor,path,_clips.local_time(clip,model.Get("playhead_time").AsDouble()),value);}return dependency.Length>0&&visible.GetValueOrDefault("values",new GArray()).AsGodotArray().Contains(value);}if(actorOwner){var definition=_definitions.get_definition(Ui<RefCounted>(inspector,"registry"),resource!.Get("type_id").AsStringName());if(definition!=null){string group=options.GetValueOrDefault("group","Properties").AsString();foreach(var value in definition.Get("properties").AsGodotArray()){var controller=value.As<Resource>();var visibility=controller.Get("options").AsGodotDictionary().GetValueOrDefault("controls_group_visibility",new Settings()).AsGodotDictionary();if(visibility.TryGetValue(group,out var accepted))return accepted.AsGodotArray().Contains(Get(controller.Get("id").AsStringName()));}}}return true;
    }
    public string animated_layout_signature(Control owner,Resource? actor)
    {
        if(actor==null)return "";var model=Ui<RefCounted>(owner,"model");var clip=_timeline.clip_for_actor_id(model,actor.Get("id").AsString());if(clip==null)return "";double time=_clips.local_time(clip,model.Get("playhead_time").AsDouble());var parts=new List<string>();if(_physics.compatible(actor)){var config=_physics.sample(actor,time);var values=new GArray();foreach(string key in new[]{"enabled","type","mode","body_mode","shape","ragdoll","constraint","bones","pins","attachment","attachment_bone","end_actor","end_bone","rope_end"})values.Add(config[key]);values.Add(config["forces"].AsGodotArray().Count);parts.Add(GD.VarToStr(values));}if(actor.Get("type_id").AsString()=="transform_image_2d"){var assets=ActorTransformationStates.Assets;var asset=_states.load_asset(assets,actor);parts.Add(_states.source_path(actor));var document=asset["document"].As<Resource>();parts.Add(document!=null?document.GetInstanceId().ToString():asset["error"].ToString());}var registry=Ui<RefCounted>(owner,"registry");foreach(var value in actor.Get("animation_tracks").AsGodotArray()){var track=value.As<Resource>();var path=track.Get("path").AsStringArray();Resource? property=null;if(path.Length==1){var definition=_definitions.get_definition(registry,actor.Get("type_id").AsStringName());if(definition!=null)property=_definitions.find_property(definition,path[0]);}else if(path.Length>1){var referenceValue=_animation.value_at_path(actor,path.Take(path.Length-1).ToArray());var reference=referenceValue.VariantType==Variant.Type.Object?referenceValue.AsGodotObject() as Resource:null;if(ActorDataOperations.ScriptIs(reference,"res://scripts/actors/core/actor_object_reference.gd")){var data=_animation.resolve_reference(reference!);var definition=data!=null?_definitions.get_object_definition(registry,data.Get("type_id").AsStringName()):null;if(definition!=null)property=_definitions.find_property(definition,path[^1]);}}if(property==null)continue;var options=property.Get("options").AsGodotDictionary();if(options.GetValueOrDefault("refresh_inspector",false).AsBool()||options.ContainsKey("controls_group_visibility"))parts.Add(string.Join(" / ",path)+"="+_tracks.sample(track,time,default));}return string.Join("|",parts);
    }
    public StyleBoxFlat resource_box(){var style=new StyleBoxFlat{BgColor=new Color("121c27"),BorderColor=new Color("38566a"),ContentMarginLeft=8,ContentMarginRight=8,ContentMarginTop=6,ContentMarginBottom=7};style.SetBorderWidthAll(1);style.SetCornerRadiusAll(7);return style;}
